package com.multideporte.backend.standing.tiebreak.controller;
import com.multideporte.backend.common.api.ApiResponse; import com.multideporte.backend.security.auth.SecurityPermissions; import com.multideporte.backend.standing.tiebreak.dto.StandingTieBreakDrawRequest; import com.multideporte.backend.standing.tiebreak.entity.StandingTieBreakDraw; import com.multideporte.backend.standing.tiebreak.service.StandingTieBreakDrawService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.ResponseEntity; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/standings/tie-break-draws") @RequiredArgsConstructor public class StandingTieBreakDrawController { private final StandingTieBreakDrawService service; @PostMapping @PreAuthorize(SecurityPermissions.CAN_MANAGE_STANDINGS) public ResponseEntity<ApiResponse<Long>> record(@Valid @RequestBody StandingTieBreakDrawRequest request) { StandingTieBreakDraw draw=service.record(request); return ResponseEntity.ok(ApiResponse.success("TIEBREAK_DRAW_RECORDED","Sorteo auditable registrado",draw.getId())); }}
